"        # 1. When major, minor, and patch are equal, a pre-release version has lower precedence than a normal version.
        if self.prerelease and not other.prerelease:
            return True
        if not self.prerelease and other.prerelease:
            return False

        # 2. Precedence for two pre-release versions with the same major, minor, and patch version
        # MUST be determined by comparing each dot separated identifier from left to right until a difference is found:
        # - Identifiers consisting of only digits are compared numerically.
        # - Identifiers with letters or hyphens are compared lexically in ASCII sort order.
        # - Numeric identifiers always have lower precedence than non-numeric identifiers.
        # - A larger set of pre-release fields has a higher precedence than a smaller set, if all of the preceding identifiers are equal.
        for p1, p2 in zip(self.prerelease, other.prerelease):
            if p1 == p2:
                continue
            if isinstance(p1, int) and isinstance(p2, int):
                return p1 < p2
            elif isinstance(p1, int) and not isinstance(p2, int):
                # Numeric identifiers always have lower precedence than non-numeric identifiers
                return True
            elif not isinstance(p1, int) and isinstance(p2, int):
                return False
            else:
                # Both are strings, compare lexically in ASCII sort order
                return p1 < p2

        return len(self.prerelease) < len(other.prerelease)"
